export type InstallationRetention = 'temporary' | 'persistent'
export type InstallationState = 'installed' | 'not_installed' | 'unknown'
/**
 * Public install outcome.
 * `verified` remains the only Host-verified success.
 * `activated` and `awaiting_user_test` are non-failure states and are not verified.
 */
export type InstallOutcome =
  | 'pending'
  | 'verified'
  | 'failed_absent'
  | 'recovery_required'
  | 'activated'
  | 'awaiting_user_test'

export interface HotReloadEvidence {
  attempted: boolean
  loaded: boolean
  method: 'already-loaded' | 'loader' | 'direct-import' | 'unsupported' | 'failed'
  reason: string
}

export interface VerificationEvidence {
  attempted: boolean
  task?: string
  exitCode?: number | null
  expectedTools: string[]
  calledTools: string[]
  resultTools: string[]
  failedTools: string[]
  sessionFiles: string[]
  receiptPath?: string
  /** Host-written process-boundary evidence. Never contains argv, prompts, output, env, or exception text. */
  launchEvidence?: {
    attempted: boolean
    processOutcome: 'returned' | 'threw'
    observerEventCount: number
    exitCode?: number | null
    signal?: string | null
    failureClass?: 'cancelled' | 'timed_out' | 'launch_error' | 'unknown'
    diagnosticHash?: string
  }
  taskResultObserved: boolean
  taskResultSha256?: string
  /** Diagnostic substring observation only. Never Host verified truth. */
  taskResultMatchedExpectation?: boolean
  observedProvider?: string
  observedModel?: string
  routeMatchedExpectation?: boolean
  layer?: VerificationLayerKind
  status?: VerificationStatus
  sourceMatched?: boolean
  /** Hash of Host-executable fixtures. Never the fixture arguments themselves. */
  fixtureDigest?: string
  reason: string
}

export interface InstallationRecord {
  schemaVersion: 1 | 2
  id: string
  createdAt: string
  /** Linked review for managed installs; adopted (workflow-external) installs have none. */
  reviewId?: string
  /** Current-policy installations are bound to the workflow that authorized them. */
  workflowId?: string
  /** Missing means managed; adopted receipts register an already-installed plugin. */
  origin?: 'managed' | 'adopted'
  targetProfile: string
  retention: InstallationRetention
  dshHome: string
  packageName: string | null
  installSpec: string
  ownedArtifactRoot?: string
  artifactSha256?: string
  /** Crash-recovery journal. `preflight_*` phases appear only on legacy receipts. */
  installPhase?: 'prepared' | 'preflight_running' | 'preflight_passed' | 'destination_installing' | 'completed'
  /** Legacy isolated-preflight evidence; current installs never write it. */
  preflight?: {
    profile: string
    passed: boolean
    sourceMatched: boolean
    verification: VerificationEvidence
  }
  /** Present on v0.1.1+ receipts. Older v0.1.0 receipts are inferred from `installed`. */
  installState?: InstallationState
  /** Fail-closed public outcome. Host-verified success is only `verified`. */
  installOutcome?: InstallOutcome
  installed: boolean
  loaded: boolean
  verified: boolean
  restartRequired: boolean
  hotReload?: HotReloadEvidence
  removed: boolean
  verification: VerificationEvidence
  /** Redacted structured facts for a failed install command. Raw stderr is never persisted. */
  installFailure?: {
    /** User/LLM-facing lifecycle stage. Never contains a command line or path. */
    stage?: 'preflight' | 'install' | 'load' | 'verify' | 'persist'
    code: string
    /** Stable human summary. `message` remains readable for legacy callers. */
    summary?: string
    message: string
    /** Whether retrying after an LLM/user repair can be meaningful. */
    retryable?: boolean
    /** Bounded, non-secret next-step suggestions for the operating LLM. */
    repairHints?: string[]
    exitCode?: number | null
    diagnosticHash?: string
    /** Host-parsed recovery evidence. Agent/user input can never populate this object. */
    recovery?: InstallFailureRecovery
  }
  /** Audit-only proof that this receipt was produced by one already-consumed sealed recovery plan. */
  recoveryAttempt?: {
    id: string
    strategy: InstallRecoveryPlan['strategy']
    sourceInstallationId: string
  }
  contributionAdvice?: {
    eligible: boolean
    reason: string
  }
  /** Host-derived canonical GitHub lineage for a successfully installed discovered capability. */
  upstreamProject?: {
    repository: string
  }
  predecessorInstallationId?: string
  supersededByInstallationId?: string
  replacement?: ReplacementJournal
}

export interface ReleaseAgePolicyEntry {
  packageName: string
  version: string
  /** Bounded, redacted pnpm reason. Never raw command output. */
  reason: string
}

export type InstallFailureRecovery =
  | {
      kind: 'minimum_release_age'
      owner: 'pnpm'
      code: 'ERR_PNPM_MINIMUM_RELEASE_AGE_VIOLATION'
      policyKey: 'minimumReleaseAge'
      entries: ReleaseAgePolicyEntry[]
      /** Host sets this only after checking the target lockfile that existed before the attempted install. */
      scope: 'host_profile' | 'unknown'
      exceptionEligible: boolean
    }
  | {
      kind: 'profile_store_mismatch'
      owner: 'pnpm'
      code: 'ERR_PNPM_UNEXPECTED_STORE'
      /** Hash of the Host-read absolute store path; the path itself is never persisted or model-visible. */
      profileStoreFingerprint?: string
      scope: 'host_profile' | 'unknown'
      reuseEligible: boolean
    }

export interface ReleaseAgeExceptionGrant {
  kind: 'minimum_release_age'
  sourceInstallationId: string
  diagnosticHash: string
  exactPackages: string[]
}

/**
 * Host-sealed semantic recovery plan. The Agent chooses only `id`; concrete
 * executor constraints are recovered from the current interrupt.
 */
export type InstallRecoveryPlan =
  | {
      id: string
      operation: 'retry_install'
      strategy: 'minimum_release_age_exception'
      sourceInstallationId: string
      diagnosticHash: string
      exactPackages: string[]
      effectScope: 'single_install_command'
    }
  | {
      id: string
      operation: 'retry_install'
      strategy: 'profile_store_reuse'
      sourceInstallationId: string
      diagnosticHash: string
      /** Binds retry to the unchanged Host-read store without disclosing its path. */
      profileStoreFingerprint: string
      effectScope: 'single_install_command'
    }

export interface InstallInput {
  /** Host-minted before any external side effect; never accepted from model tool arguments. */
  installationId?: string
  reviewId: string
  targetProfile: string
  /** Every adopted capability is persisted; the installer rejects anything else. */
  retention: InstallationRetention
  /** Host-derived managed-source artifact hash; never accepted from model tool arguments. */
  expectedArtifactSha256?: string
  /** Host-owned same-package replacement binding. Never accepted from model tool arguments. */
  replacement?: ReplacementTarget
  /** Host-derived from a sealed failed receipt and the Agent-selected recovery id. */
  recoveryPlan?: InstallRecoveryPlan
}

